      "layout": "standardStudy",
      "translation": "men",
      "explanation": [
        "Hovudtanke: aber er konjunksjonen 'men', som set to tankar opp mot kvarandre: Ich will kommen, aber ich habe keine Zeit.",
        "Det endrar ikkje ordstillinga: aber står på plass 0, og verbet kjem etterpå som i ei vanleg setning. Framfor aber set ein vanlegvis komma.",
        "I talemål kan aber òg vere ein partikkel som forsterkar overrasking: Das ist aber schön! (Så fint det er, då!). Som svar tyder Aber gern! 'Ja, gjerne!'."
      ],
      "examples": [
        {
          "de": "Ich möchte kommen, aber ich habe keine Zeit.",
          "lv": "Eg vil gjerne kome, men eg har ikkje tid."
        },
        {
          "de": "Das Auto ist alt, aber es fährt gut.",
          "lv": "Bilen er gammal, men han går godt."
        },
        {
          "de": "Er ist klein, aber stark.",
          "lv": "Han er liten, men sterk."
        },
        {
          "de": "Das ist aber schön!",
          "lv": "Så fint det er, då!"
        },
        {
          "de": "Kann ich dir helfen? – Aber gern!",
          "lv": "Kan eg hjelpe deg? – Ja, gjerne!"
        }
      ],
      "comparison": [
        {
          "word": "sondern",
          "meaning": "men (etter ei nekting)",
          "example": "Er ist nicht dumm, sondern faul. – Han er ikkje dum, men lat."
        },
        {
          "word": "doch",
          "meaning": "likevel",
          "example": "Es regnet, doch wir gehen raus. – Det regnar, men vi går ut likevel."
        },
        {
          "word": "und",
          "meaning": "og",
          "example": "Ich lese und schreibe. – Eg les og skriv."
        }
      ],
