        "Ordet vert ikkje bøygd. Bitte schön er ein høflegare variant når ein rekkjer nokon noko ('ver så god'), bitte sehr er ein likeverdig variant. Wie bitte? tyder 'kva sa du?' når du ikkje har høyrt.",
        "Substantivet die Bitte med stor forbokstav tyder 'bøn, oppmoding' – det er eit anna ord."
