        "Same form die vert brukt i fleirtal for alle kjønn i nominativ og akkusativ: die Kinder, die Autos, die Tische. I dativ heiter det der (hokjønn) og den (fleirtal, med -n på substantivet).",
        "Die kan òg vere eit peikande eller relativt pronomen: die Frau, die dort steht."
