        "Hovudtanke: ein er den ubestemte artikkelen: ein Mann, eine Frau, ein Kind. Han viser at substantivet er nytt eller ubestemt (ein mann, ei kvinne).",
        "Hankjønn og inkjekjønn har ein, hokjønn eine. I akkusativ har hankjønn einen: Ich habe einen Bruder. I dativ: einem (hankjønn/inkjekjønn), einer (hokjønn). Det finst ingen ubestemt artikkel i fleirtal; ved nekting brukar ein kein.",
