      "explanation": [
        "Hovudpoeng: hübsch er adjektivet «pen, søt» – om utsjånad, klede, hus og ting som er fine å sjå på. Det er mildare enn schön (vakker).",
        "Framfor eit substantiv blir hübsch bøygd som eit vanleg adjektiv: ein hübsches Kleid, eine hübsche Frau, hübsche Blumen. Komparativ: hübscher, superlativ: am hübschesten.",
        "I daglegtale kan ganz hübsch også tyde «ganske mykje, svært»: Das war ganz hübsch teuer."
      ],
      "examples": [
        {
          "de": "Sie ist ein hübsches Mädchen.",
          "lv": "Ho er ei pen jente."
        },
        {
          "de": "Das Kleid ist wirklich hübsch.",
          "lv": "Kjolen er verkeleg pen."
        },
        {
          "de": "Was für ein hübsches Haus!",
          "lv": "For eit pent hus!"
        },
        {
          "de": "Du siehst heute hübsch aus.",
          "lv": "Du ser pen ut i dag."
        }
      ],
      "comparison": [
        {
          "word": "schön",
          "meaning": "vakker",
          "example": "Das Wetter ist schön. – Vêret er vakkert."
        },
        {
          "word": "süß",
          "meaning": "søt (også om smak)",
          "example": "Das Baby ist süß. – Babyen er søt."
        },
        {
          "word": "schick",
          "meaning": "elegant, flott",
          "example": "Du siehst schick aus. – Du ser elegant ut."
        }
      ],
      "tip": [
        "Hübsch blir brukt som eit mildt kompliment, schön som eit sterkare.",
        "Legg til ending når ordet står framfor eit substantiv: ein hübsches Kleid, men Das Kleid ist hübsch."
      ],
      "important": [
        "Om menn blir hübsch brukt sjeldnare; oftare seier ein gut aussehend eller attraktiv.",
        "Hübsch er mykje brukt i daglegtale, men er ikkje det same som schön – schön er meir generelt og sterkare."
      ],
