      "explanation": [
        "Hovudpoeng: können (kunne, klare) er eit modalverb. Det uttrykkjer evne (Er kann schwimmen – han kan symje), moglegheit (Wir können heute kommen – vi kan kome i dag) og oppmoding (Kannst du mir helfen? – Kan du hjelpe meg?).",
        "Former: ich kann, du kannst, er/sie/es kann, wir können, ihr könnt, sie können; preteritum konnte, perfektum hat gekonnt. Det andre verbet står i infinitiv sist i setninga: Ich kann heute nicht kommen.",
        "Om språk og ferdigheiter kan können òg stå utan eit anna verb: Ich kann Deutsch (eg kan tysk)."
      ],
      "examples": [
        {
          "de": "Ich kann Deutsch sprechen.",
          "lv": "Eg kan snakke tysk."
        },
        {
          "de": "Kannst du mir helfen?",
          "lv": "Kan du hjelpe meg?"
        },
        {
          "de": "Wir können heute kommen.",
          "lv": "Vi kan kome i dag."
        },
        {
          "de": "Er kann gut schwimmen.",
          "lv": "Han kan symje godt."
        },
        {
          "de": "Sie kann leider nicht kommen.",
          "lv": "Ho kan dessverre ikkje kome."
        }
      ],
      "comparison": [
        {
          "word": "dürfen",
          "meaning": "få lov til",
          "example": "Hier darf man nicht rauchen. – Her får ein ikkje røykje."
        },
        {
          "word": "müssen",
          "meaning": "måtte, vere nøydd til",
          "example": "Ich muss arbeiten. – Eg må arbeide."
        },
        {
          "word": "kennen",
          "meaning": "kjenne",
          "example": "Ich kenne ihn. – Eg kjenner han."
        }
      ],
      "tip": [
        "Ich kann, er kann – i 1. og 3. person eintal er det inga ending: ich kann, er kann.",
        "Å kunne noko (eit språk, eit spel) kan òg uttrykkjast utan verb: Kannst du Schach? – Kan du sjakk?"
      ],
      "important": [
        "Ikkje bland können og kennen: können – kunne/klare, kennen – kjenne.",
        "I perfektum brukar modalverb vanlegvis ei erstatningsform: Ich habe nicht kommen können (infinitiv til slutt)."
      ],
