        "Komparativ: lauter (høgare), superlativ: am lautesten. Framfor substantiv: ein lauter Knall, laute Musik. Motsetnaden er leise.",
        "Laut er òg ein preposisjon som tyder «ifølgje» (laut Gesetz – ifølgje lova), men det er eit anna ord; substantivet der Laut tyder «lyd»."
