        "Fleirtal: die Männer (menn, med omlyd). Genitiv: des Mannes, dativ fleirtal: den Männern. I samansetjingar: Ehemann, Geschäftsmann (fleirtal Geschäftsleute).",
        "Skilnaden frå man: man (ein, folk) er eit pronomen og vert skrive med liten forbokstav og éin n. Mennesket generelt heiter der Mensch."
