      "explanation": [
        "Hovudpoeng: natürlich er både adverb og adjektiv. Som svar tyder natürlich «sjølvsagt»: Kommst du mit? – Natürlich! Som adjektiv tyder det «naturleg»: natürliche Haare, eine natürliche Reaktion.",
        "Adjektivet får endingar: eine natürliche Farbe, ein natürliches Verhalten. Komparativ: natürlicher, superlativ: am natürlichsten.",
        "Motsetnad: künstlich (kunstig)."
      ],
      "examples": [
        {
          "de": "Kommst du mit? – Natürlich!",
          "lv": "Blir du med? – Sjølvsagt!"
        },
        {
          "de": "Natürlich helfe ich dir.",
          "lv": "Sjølvsagt hjelper eg deg."
        },
        {
          "de": "Das ist eine natürliche Reaktion.",
          "lv": "Det er ein naturleg reaksjon."
        },
        {
          "de": "Sie hat natürliche rote Haare.",
          "lv": "Ho har naturleg raudt hår."
        }
      ],
      "comparison": [
        {
          "word": "klar",
          "meaning": "klart; sjølvsagt",
          "example": "Klar, ich komme. – Klart, eg kjem."
        },
        {
          "word": "selbstverständlich",
          "meaning": "sjølvsagt, ei sjølvfølgje",
          "example": "Selbstverständlich helfe ich. – Sjølvsagt hjelper eg."
        },
        {
          "word": "künstlich",
          "meaning": "kunstig",
          "example": "Das ist künstliches Licht. – Det er kunstig lys."
        }
      ],
      "tip": [
        "Natürlich! er ein av dei vanlegaste måtane å seie «sjølvsagt» på.",
        "Natürlich kan stå først eller midt i setninga: Natürlich komme ich. / Ich helfe dir natürlich."
      ],
      "important": [
        "Natürlich og künstlich er motsetnader.",
        "Legg merke til: natürlich i tydinga «naturleg» får ending framfor substantiv."
      ],
