        "Måltid uttrykkjer ein med zu: zu Mittag essen (ete middag midt på dagen), zu Abend essen (ete kveldsmat). Ein kan også bruke essen utan objekt om sjølve måltidet: Wir essen um sieben.",
        "Når eit dyr et, brukar ein fressen; når ein snakkar om maten som substantiv, skriv ein das Essen."
